def parse_music(music_string: str) -> List[int]:
    beats_map = {'o': 4, 'o|': 2, '.|': 1}
    result = []
    current_note = ''

    for char in music_string + ' ':
        if char == '|':
            note_key = current_note + '|'
            result.append(beats_map[note_key])
            current_note = ''
        elif char.isspace():
            if current_note:
                note_key = current_note
                result.append(beats_map[note_key])
                current_note = ''
        else:
            current_note += char

    return result

